"""Publication display names for the fixed 28 structural motifs."""
FRAGMENT_ORDER = ('acetoxy', 'alcohol_sp3', 'aliphatic_ketone', 'conjugated_enone', 'ester', 'exocyclic_methylene', 'fused_6_5_C_with_oxygenated', 'fused_6_6_C_nonarom_no_double_no_ketone', 'fused_6_6_C_with_alkene', 'fused_6_6_C_with_oxygenated', 'fused_four_ring_C_system', 'gem_dimethyl_ring', 'hydroxy_methine', 'oxygenated_methylene', 'ring_5_C_oxygenated', 'ring_5_nonarom_0db', 'ring_6_C_aromatic_benzene', 'ring_6_C_oxygenated', 'ring_6_C_ring_ketone', 'ring_6_C_sp3_only', 'ring_6_nonarom_1db', 'triring_6_6_5_C', 'triring_6_6_5_C_oxygenated', 'triring_6_6_6_C', 'triring_6_6_6_C_alkene_present', 'triring_6_6_6_C_ketone_present', 'triring_6_6_6_C_no_aromatic', 'triring_6_6_6_C_oxygenated')
FRAGMENT_NAMES = {'acetoxy': 'Acetoxy group', 'alcohol_sp3': 'Hydroxyl group on an sp³ carbon', 'aliphatic_ketone': 'Aliphatic ketone', 'conjugated_enone': 'α,β-Unsaturated ketone (enone)', 'ester': 'Ester group', 'exocyclic_methylene': 'Exocyclic methylene group', 'fused_6_5_C_with_oxygenated': 'Oxygen-substituted fused 6/5 carbocyclic motif', 'fused_6_6_C_nonarom_no_double_no_ketone': 'Nonaromatic fused 6/6 carbocyclic motif without endocyclic C=C or ring ketone', 'fused_6_6_C_with_alkene': 'Fused 6/6 carbocyclic motif with an endocyclic C=C bond', 'fused_6_6_C_with_oxygenated': 'Oxygen-substituted fused 6/6 carbocyclic motif', 'fused_four_ring_C_system': 'Fused tetracyclic carbocyclic motif (5- and/or 6-membered rings)', 'gem_dimethyl_ring': 'Gem-dimethyl group on a quaternary ring carbon', 'hydroxy_methine': 'Oxygen-substituted sp³ methine', 'oxygenated_methylene': 'Oxygen-substituted sp³ methylene', 'ring_5_C_oxygenated': 'Oxygen-substituted five-membered carbocycle', 'ring_5_nonarom_0db': 'Nonaromatic five-membered carbocycle without endocyclic C=C', 'ring_6_C_aromatic_benzene': 'Benzene ring', 'ring_6_C_oxygenated': 'Oxygen-substituted six-membered carbocycle', 'ring_6_C_ring_ketone': 'Six-membered carbocyclic ketone', 'ring_6_C_sp3_only': 'Six-membered all-sp³ carbocycle', 'ring_6_nonarom_1db': 'Nonaromatic six-membered carbocycle with one endocyclic C=C bond', 'triring_6_6_5_C': 'Fused 6/6/5 carbocyclic motif', 'triring_6_6_5_C_oxygenated': 'Oxygen-substituted fused 6/6/5 carbocyclic motif', 'triring_6_6_6_C': 'Fused 6/6/6 carbocyclic motif', 'triring_6_6_6_C_alkene_present': 'Fused 6/6/6 carbocyclic motif with an endocyclic C=C bond', 'triring_6_6_6_C_ketone_present': 'Fused 6/6/6 carbocyclic motif containing a ring ketone', 'triring_6_6_6_C_no_aromatic': 'Nonaromatic fused 6/6/6 carbocyclic motif', 'triring_6_6_6_C_oxygenated': 'Oxygen-substituted fused 6/6/6 carbocyclic motif'}
FRAGMENT_CODES = {'acetoxy': 'F01', 'alcohol_sp3': 'F02', 'aliphatic_ketone': 'F03', 'conjugated_enone': 'F04', 'ester': 'F05', 'exocyclic_methylene': 'F06', 'fused_6_5_C_with_oxygenated': 'F07', 'fused_6_6_C_nonarom_no_double_no_ketone': 'F08', 'fused_6_6_C_with_alkene': 'F09', 'fused_6_6_C_with_oxygenated': 'F10', 'fused_four_ring_C_system': 'F11', 'gem_dimethyl_ring': 'F12', 'hydroxy_methine': 'F13', 'oxygenated_methylene': 'F14', 'ring_5_C_oxygenated': 'F15', 'ring_5_nonarom_0db': 'F16', 'ring_6_C_aromatic_benzene': 'F17', 'ring_6_C_oxygenated': 'F18', 'ring_6_C_ring_ketone': 'F19', 'ring_6_C_sp3_only': 'F20', 'ring_6_nonarom_1db': 'F21', 'triring_6_6_5_C': 'F22', 'triring_6_6_5_C_oxygenated': 'F23', 'triring_6_6_6_C': 'F24', 'triring_6_6_6_C_alkene_present': 'F25', 'triring_6_6_6_C_ketone_present': 'F26', 'triring_6_6_6_C_no_aromatic': 'F27', 'triring_6_6_6_C_oxygenated': 'F28'}
def fragment_name(fragment_id: str) -> str:
    return FRAGMENT_NAMES.get(str(fragment_id), str(fragment_id))
def fragment_label(fragment_id: str) -> str:
    key = str(fragment_id)
    return f"{FRAGMENT_CODES[key]}  {FRAGMENT_NAMES[key]}" if key in FRAGMENT_CODES else key
def fragment_code(fragment_id: str) -> str:
    return FRAGMENT_CODES.get(str(fragment_id), str(fragment_id))
